use std::env;
fn dec(s:&str)->String{let a="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".as_bytes();let mut out=Vec::new();let mut v:u32=0;let mut bits=0;for c in s.bytes(){if c==b'='{break}if let Some(p)=a.iter().position(|x|*x==c){v=(v<<6)|p as u32;bits+=6;if bits>=8{bits-=8;out.push(((v>>bits)&255)as u8)}}}String::from_utf8(out).unwrap()}
fn enc(s:&str)->String{let a=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let b=s.as_bytes();let mut o=String::new();let mut i=0;while i<b.len(){let x=b[i]as u32;let y=if i+1<b.len(){b[i+1]as u32}else{0};let z=if i+2<b.len(){b[i+2]as u32}else{0};let t=(x<<16)|(y<<8)|z;o.push(a[(t>>18)as usize]as char);o.push(a[((t>>12)&63)as usize]as char);o.push(if i+1<b.len(){a[((t>>6)&63)as usize]as char}else{'='});o.push(if i+2<b.len(){a[(t&63)as usize]as char}else{'='});i+=3}o}
fn main(){let a:Vec<String>=env::args().skip(1).collect();let v=&a[0];let op=&a[1];let loc=&a[2];let x=dec(&a[3]);let y=if a.len()>4{dec(&a[4])}else{String::new()};if v=="ascii_compare"{println!("{{\"status\":\"ok\",\"kind\":\"bool\",\"value\":{},\"effective_locale\":\"root\"}}",x.eq_ignore_ascii_case(&y));return}if v=="normalizer"{println!("{{\"status\":\"unsupported\",\"error\":\"no_standard_library_normalization\",\"effective_locale\":\"root\"}}");return}let r=if v=="ascii"{if op=="lower"{x.to_ascii_lowercase()}else{x.to_ascii_uppercase()}}else{if op=="lower"{x.to_lowercase()}else{x.to_uppercase()}};println!("{{\"status\":\"ok\",\"kind\":\"string\",\"value_b64\":\"{}\",\"effective_locale\":\"{}\"}}",enc(&r),if v=="unicode_default"{"root"}else{loc});}
